t.script:
async function loadChallenge() {

    const token = document.getElementById(
        'challenge_token'
    ).value

    const response = await fetch(
        `/mobile-sim/challenge/${token}`,
        {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: '{}'
        }
    )

    const data = await response.json()

    if (!data.result.success) {
        return
    }

    const challenge = data.result.challenge

    document.getElementById(
        'challenge-detail'
    ).innerHTML = `





${challenge.action}



                Status:
                ${challenge.status}




                Approve





                Reject





    `
}
